# posters
grid_lines=''.join(f'<div style="position:absolute;left:{x}%;top:0;bottom:0;width:1px;background:{AUB}22"></div>' for x in (10,50,90))+''.join(f'<div style="position:absolute;top:{y}%;left:0;right:0;height:1px;background:{AUB}22"></div>' for y in (8,92))
