pos3=f'<div style="position:relative;width:340px;height:480px;background:{LIME};overflow:hidden">{"".join(f"<div style=&quot;position:absolute;left:{(c*230-90+(r%2)*115)}px;top:{r*72-10}px;width:230px;color:{AUB}&quot;>{lk(AUB,chr(109)+chr(103))}</div>".replace("&quot;",chr(34)) for r in range(6) for c in range(3))}<div style="position:absolute;left:0;right:0;bottom:0;height:150px;background:{AUB};display:flex;align-items:center;justify-content:center"><div style="width:220px">{lk(IVORY,"lk")}</div></div></div>'
P.append(page('#fff',hdr('3.9','Layout & poster system','نظام التخطيط والبوستر','VISUAL')+f'<div class="abs" style="left:110px;top:170px;display:flex;gap:40px">{pos1}{pos2}{pos3}</div><div class="abs rtl" style="right:110px;top:190px;width:300px;font-size:19px;line-height:1.75"><div class="eyebrow" style="direction:ltr;text-align:right">RULES</div><p style="margin:12px 0">• شبكة 12 عمودًا، هوامش 8%.<br>• عنوان واحد كبير، لا أكثر من ثلاثة مستويات.<br>• الشعار أسفل اليسار دائمًا.<br>• قصّ الأقواس والحرف m حتى الحافة.<br>• لون واحد مهيمن للصفحة.</p></div>'))
# icons
icn=''.join(f'<div style="background:{IVORY};border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;height:128px"><div style="width:56px;height:56px;color:{AUB}">{A2.icon_inline(n)}</div><div style="font-size:12px;letter-spacing:2px;opacity:.55;font-weight:700">{n.upper()}</div></div>' for n in A2.ICONS)
